export function WarningState({
  title = "{{title}}",
  message = "{{message}}",
  severity = "{{severity}}",
  acknowledged = {{acknowledged}},
}) {
  const palette = severity === "danger"
    ? { bg: "color-mix(in srgb, #B3261E 10%, #FAF7F2)", border: "#B3261E", icon: "#B3261E" }
    : { bg: "color-mix(in srgb, #E8A020 14%, #FAF7F2)", border: "#B4790A", icon: "#B4790A" };
  return (
    <div role="alert" style={{ display: "flex", alignItems: "flex-start", gap: 12, maxWidth: 400, padding: "14px 16px",
      boxSizing: "border-box", borderRadius: 10, border: `1.5px solid ${palette.border}`, background: palette.bg,
      font: "13.5px/1.45 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ fontSize: 18, flexShrink: 0, marginTop: 1, color: palette.icon }}>▲</span>
      <div>
        <p style={{ margin: "0 0 2px", fontWeight: 700 }}>{title}</p>
        <p style={{ margin: "0 0 8px", color: "#241430b3" }}>{message}</p>
        <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, cursor: "pointer" }}>
          <input type="checkbox" checked={acknowledged} readOnly />
          I understand the consequences
        </label>
      </div>
    </div>
  );
}
